Lemma AHttpCat_to_internal : forall m g, AHttpCat m g ->
  rw_cells bsegs m 6684368 (hc_cells g (zeros 52) (zeros 4)) /\ rw_cells bsegs m 6684424 (hg_cells (if g then 1 else 0) (if g then 1 else 0) (zeros 6)).
Proof.
  intros m g [OB GD]. unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD in *. destruct g; cbn [AHttpCatCells AHttpCatGuardCells] in OB, GD; split.
  - eapply rw_cells_reshape; [exact OB | cbn; repeat split; reflexivity | vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact GD | cbn; repeat split; reflexivity | vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact OB | cbn; repeat split; reflexivity | vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact GD | cbn; repeat split; reflexivity | vm_compute; reflexivity].
Qed.

Lemma AHttpCat_of_internal : forall m,
  rw_cells bsegs m 6684368 (hc_cells true [] (zeros 4)) -> rw_cells bsegs m 6684424 (hg_cells 1 1 (zeros 6)) ->
  AHttpCat m true.
Proof.
  intros m OB GD. unfold AHttpCat, AG_HTTP_CAT, AG_HTTP_CAT_GUARD. cbn [AHttpCatCells AHttpCatGuardCells]. split.
  - eapply rw_cells_reshape; [exact OB | cbn; repeat split; reflexivity | vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact GD | cbn; repeat split; reflexivity | vm_compute; reflexivity].
Qed.

